def modified_encode(lst):
    if not lst:
        return []

    result = []
    count = 1
    current = lst[0]

    for i in range(1, len(lst)):
        if lst[i] == current:
            count += 1
        else:
            if count > 1:
                result.append([count, current])
            else:
                result.append(current)
            current = lst[i]
            count = 1

    # Handle the last group
    if count > 1:
        result.append([count, current])
    else:
        result.append(current)

    return result

