from collections import Counter

def max_occurrences(lst):
    if not lst:
        return (None, 0)

    counts = Counter(lst)
    max_count = max(counts.values())

    # Find the first item with max_count to ensure deterministic behavior
    for item in lst:
        if counts[item] == max_count:
            return (item, max_count)

